CE(a){return"\u0413\u0440\u0435\u0448\u043a\u0430 \u043f\u0440\u0438 \u0437\u0430\u043f\u0430\u0437\u0432\u0430\u043d\u0435 \u043d\u0430 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438\u0442\u0435: "+a},
gDz(){return"\u041e\u0431\u043d\u043e\u0432\u0438 \u043e\u0441\u043d\u043e\u0432\u043d\u0438\u0442\u0435 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438"},
gDE(){return"\u041e\u0431\u043d\u043e\u0432\u0438 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438\u0442\u0435 \u043d\u0430 \u0440\u0430\u0434\u0438\u043e\u0442\u043e"},
gDG(){return"\u041e\u0431\u043d\u043e\u0432\u0438 TX \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0442\u0430"},
gDD(){return"\u041e\u0431\u043d\u043e\u0432\u0438 \u043f\u0440\u0435\u043f\u0440\u0430\u0449\u0430\u043d\u0435\u0442\u043e \u043d\u0430 \u043f\u0430\u043a\u0435\u0442\u0438"},
gDA(){return"\u041e\u0431\u043d\u043e\u0432\u0438 \u0434\u043e\u0441\u0442\u044a\u043f\u0430 \u0437\u0430 \u0433\u043e\u0441\u0442\u0438"},
DH(a){return a+" \u0435 \u043e\u0431\u043d\u043e\u0432\u0435\u043d\u043e"},
CD(a){return"\u0413\u0440\u0435\u0448\u043a\u0430 \u043f\u0440\u0438 \u043e\u0431\u043d\u043e\u0432\u044f\u0432\u0430\u043d\u0435 \u043d\u0430 "+a},
gCd(){return"CLI \u043d\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u0435\u043b\u044f"},
gCr(){return"\u041e\u0442\u0441\u0442\u0440\u0430\u043d\u0438 \u0441\u043b\u0435\u0434\u0432\u0430\u0449\u0430\u0442\u0430 \u043a\u043e\u043c\u0430\u043d\u0434\u0430"},
