gDe(){return"\u0421\u043b\u0435\u0434\u0432\u0430\u0449\u0430 \u043a\u043e\u043c\u0430\u043d\u0434\u0430"},
gCx(){return"\u0412\u044a\u0432\u0435\u0434\u0435\u0442\u0435 \u043f\u044a\u0440\u0432\u043e \u043a\u043e\u043c\u0430\u043d\u0434\u0430."},
gA7(){return"\u0420\u0430\u043c\u043a\u0430 \u043d\u0430 CLI \u043a\u043e\u043c\u0430\u043d\u0434\u0430"},
A6(a){return"\u0413\u0440\u0435\u0448\u043a\u0430: "+a},
gC7(){return"\u0412\u0437\u0435\u043c\u0438 \u0438\u043c\u0435"},
gC8(){return"\u0412\u0437\u0435\u043c\u0438 \u0440\u0430\u0434\u0438\u043e"},
gC9(){return"\u0412\u0437\u0435\u043c\u0438 TX"},
gCa(){return"\u0421\u044a\u0441\u0435\u0434\u0438"},
