gCU(){return"\u041f\u043e\u0440\u043e\u0433\u043e\u0432\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u0432\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e \u0434\u043b\u044f \u043a\u0430\u043b\u0456\u0431\u0440\u0443\u0432\u0430\u043d\u043d\u044f \u0448\u0443\u043c\u043e\u0432\u043e\u0433\u043e \u0440\u0456\u0432\u043d\u044f \u0440\u0430\u0434\u0456\u043e, \u0449\u043e\u0431 \u0432\u0456\u0434\u0445\u0438\u043b\u044f\u0442\u0438 \u0441\u0438\u0433\u043d\u0430\u043b\u0438, \u0449\u043e \u043f\u0435\u0440\u0435\u0432\u0438\u0449\u0443\u044e\u0442\u044c \u0446\u0435\u0439 \u0440\u0456\u0432\u0435\u043d\u044c. 0 \u2013 \u0432\u0438\u043c\u043a\u043d\u0435\u043d\u043e; \u0430\u043a\u0442\u0438\u0432\u0443\u0439\u0442\u0435 \u043b\u0438\u0448\u0435 \u0443 \u0440\u0430\u0437\u0456 \u0432\u0438\u044f\u0432\u043b\u0435\u043d\u043d\u044f \u043f\u043e\u043c\u0438\u043b\u043e\u043a RX \u0443 \u0448\u0443\u043c\u043d\u043e\u043c\u0443 \u0434\u0456\u0430\u043f\u0430\u0437\u043e\u043d\u0456."},
